def get_total_number_of_sequences(m, n):
    # Helper function to calculate the number of valid sequences starting from a specific value
    def count_sequences(start, remaining_length, m, dp):
        if remaining_length == 0:
            return 1

        if start * (2 ** remaining_length) - 1 > m:
            return 0

        if dp[start][remaining_length] != -1:
            return dp[start][remaining_length]

        count = 0
        for i in range(2 * start, min(m + 1, 2 * start + remaining_length)):
            if i <= m:
                count += count_sequences(i, remaining_length - 1, m, dp)

        dp[start][remaining_length] = count
        return count

    dp = [[-1] * (n + 1) for _ in range(m + 1)]
    total_sequences = 0

    for start in range(1, m + 1):
        if start * (2 ** (n - 1)) <= m:
            total_sequences += count_sequences(start, n - 1, m, dp)

    return total_sequences

