To solve the problem of finding the largest sum of a contiguous array in a modified array formed by repeating the given array `k` times, we need to consider several approaches. One efficient way to solve this is to use a combination of Kadane's algorithm for finding the maximum subarray sum and additional logic to handle the repeated array case.

Here is the Python function that accomplishes this:

```python
def max_sub_array_sum_repeated(arr, n, k):
    def kadane(A, start, end):
        if end < start:
            return -float('inf')
        if not start < end:
            return A[start]
        max_ending_here = max_so_far = A[start]
        for i in range(start+1, end):
            max_ending_here = max(A[i], max_ending_here + A[i])
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    def max_sub_array(A, n, k):
        if k == 1:
            return kadane(A, 0, n)
        sum_ending_here = 0
        max_ending_here = A[0]
        sum_A = A[0]
        for i in range(1, n):
            max_ending_here = max(max_ending_here, max(A[i], max_ending_here + A[i]))
            sum_ending_here = max(0, sum_ending_here + A[i])
            sum_A += A[i]
        max_ending_here = max(max_ending_here, sum_ending_here)
        if k == 2:
            return max(max_ending_here, sum_A)
        max_loop = max(0, sum_ending_here) + (k - 2) * max(0, sum_A)
        return max(max_ending_here, max_loop + sum_A)

    max_single = max_sub_array(arr, n, 1)
    max_repeated = max_sub_array(arr, n, k)
    return max(max_single, max_repeated)

# Test cases
